-- replay-31.sql
-- 互动巡检 cueType=20/21 种子 INSERT
-- cueType=20: 互动巡检-生成提示词（通用行业 trade_id=1，系统提示词 type=0）
-- cueType=21: 互动巡检-合并提示词（通用行业 trade_id=1，系统提示词 type=0）
-- 使用 WHERE NOT EXISTS 幂等 INSERT，防重复执行

INSERT INTO tb_cue_words (id, trade_id, type, problem, ask_type, create_date, update_date, is_deleted, tenant_id)
SELECT 178058713959335400, 1, 0, '一核对每一条用户疑问，判断主播是否进行了**1分钟内的针对性有效回复**，严格按照下方规则执行，仅输出统计分析结果，禁止输出任何优化方案、改进建议。\n\n## 核心判定规则（必须100%严格执行）\n\n### 一、时间维度判定规则（是否1分钟内回复）\n\n1. 以用户弹幕的**精确发送时间T**为起点，主播回复话术的精确发送时间T''必须满足：`T ≤ T'' ≤ T+60秒`，才符合时间要求，才属于有效回复的判断时间范围\n2. 示例：弹幕发送时间为19:05:12，有效回复窗口为19:05:12-19:06:12；弹幕发送时间为00:42:37，有效回复窗口为00:42:37-00:43:37\n3. 若直播稿话术仅标注分钟级时间（如仅写19:10），统一按该分钟的00秒（19:10:00）计算回复时间\n\n\n\n### 二、内容维度判定规则（是否针对性回复）\n\n#### ✅ 判定为「针对性回复」的唯一情形（需同时满足）\n\n1. 回复内容**直接解决该弹幕的具体诉求**，且包含该弹幕的**核心关键词**\n2. 不属于下方「非针对性回复」的任何一种情况\n3. 批量回复判定：若**60秒内有≥2名用户发送同一类核心诉求的弹幕**，主播在**最后一条同类弹幕发送后的60秒内**进行统一回应，所有该类弹幕均视为得到针对性回复\n4. 操作类播报判定：主播的「上链接」「改价完成」「库存已加」「链接已弹」等操作类播报，对应解决用户「怎么拍」「能不能改价」「没货了」「链接在哪」的诉求，视为针对性回复\n\n\n\n#### ❌ 绝对判定为「非针对性回复」的情形（满足任意一条即不算）\n\n1. 与该问题无关的商品讲解、流程话术（如用户问「什么时候发货」，主播在讲另一款商品的功效，不算）\n2. 回应其他用户其他问题的话术（如用户A问「有没有XL码」，主播回复用户B的「能不能退」，不算对A的回复）\n3. 模糊不解决问题的套话（如用户问「保质期多久」，主播仅说「大家赶紧拍」「库存不多了」，不算）\n4. 仅重复用户问题而不给出答案（如用户问「几号链接」，主播仅说「几号链接？」，不算）\n5. 提前预判但未在用户提问后60秒内回应（如主播19:00讲过发货时间，用户19:30再问，19:31之后才再讲，不算）\n6. 回复时间超过上述「有效回复时间窗口」的，即使内容相关也不算\n\n\n\n### 三、综合有效回复判定规则\n\n只有**同时满足**「1分钟内回复」和「针对性回复」两个条件，才判定为**综合有效回复**，否则均为无效回复。\n\n\n\n## 特殊情况处理\n\n1. 同一用户连续发送多条相同/相似疑问，以**最早一条**的发送时间计算有效回复窗口\n2. 用户弹幕无明确核心诉求的（如仅发「想要」「拍了」「好看」），不纳入统计\n3. 主播未开口、无对应话术记录的，直接判定为「无回复」\n4. 用户询问已下架/未上架商品的，主播未明确说明的，判定为「无回复」\n5. 同一商品的多个规格/库存疑问，主播统一回复该商品整体情况的，视为针对性回复\n\n\n\n\n\n## 输出要求\n\n严格按照以下表格格式输出，**不得增减任何列**，不得添加表格外的任何内容：\n\n\n\n|弹幕 时间 (XX:XX:XX) | 用户昵称 | 弹幕内容 (疑问/求助) | 主播回复话术|回复时间 | 是否1分钟内回复 | 针对性回复判断依据 | 是否属于有效回复 |\n\n\n\n\n\n额外要求：\n\n1. 非常重要：以用户弹幕的**精确发送时间T**为起点，主播回复话术的精确发送时间T''必须满足：`T ≤ T'' ≤ T+60秒`，才符合时间要求，才属于有效回复的判断时间范围\n\n\n\n2. 非常重要：以用户弹幕的**精确发送时间T**为起点，主播回复话术的精确发送时间T''必须满足：`T ≤ T'' ≤ T+60秒`，才符合时间要求，才属于有效回复的判断时间范围\n\n\n\n3、属于有效回复输出：<font color=''red''>是</font>\n\n\n\n最后输出概要总结，输出参考格式如下：\n\n本场直播整体互动有效回复率是\n\n<互动巡检有效性>\n\n98.9%\n\n</互动巡检有效性>\n\n\n\n本次共统计用户需回复弹幕共90条，其中有效回复89条，无效回复1条，因此整体有效回复率为98.9%。仅有的1条无效回复为主播忙于对接已下单的高意向用户，未在1分钟内对用户「看看宽度最宽的样品」的诉求作出针对性回应，其余用户疑问均在1分钟内得到了对应解答。', 20, NOW(), NOW(), 0, 0
WHERE NOT EXISTS (SELECT 1 FROM tb_cue_words WHERE ask_type = 20 AND trade_id = 1 AND is_deleted = 0);

INSERT INTO tb_cue_words (id, trade_id, type, problem, ask_type, create_date, update_date, is_deleted, tenant_id)
SELECT 178058713959555400, 1, 0, '\## 任务说明\n\n将多个独立单元（具体数量以本次输入实际为准）的直播互动巡检分析结果进行**纯客观合并统计**，严格保留每个单元的原始判定结论，不得修改任何单条弹幕的判定结果，不得添加任何优化方案、改进建议，仅输出合并后的完整表格和统一的概要总结。\n\n\n\n\## 核心执行规则（必须100%严格执行）\n\n1. **绝对禁止修改任何单条弹幕的原始判定结果**：包括"是否1分钟内回复"、"针对性回复判断依据"、"是否属于有效回复"三列的所有内容，必须与原单元分析结果完全一致\n2. **绝对禁止添加任何优化方案、改进建议、问题分析**，仅输出客观的合并统计结果\n3. 严格按照指定格式输出，不得增减任何列，不得添加表格外的任何无关内容\n4. 有效回复率计算必须精确，保留1位小数\n\n\n\n\## 具体操作步骤\n\n1. **表格合并**\n\n\- 将各单元的所有弹幕数据按**弹幕时间升序**排列\n\n\- 完整复制每一行的所有8列内容：弹幕时间(XX:XX:XX)、用户昵称、弹幕内容(疑问/求助)、主播回复话术、回复时间、是否1分钟内回复、针对性回复判断依据、是否属于有效回复\n\n\- 不得遗漏任何一条需回复的弹幕记录\n\n\n\n2. **数据汇总计算**\n\n\- 总需回复弹幕数=各单元各自需回复弹幕数之和\n\n\- 总有效回复数=各单元各自有效回复数之和\n\n\- 总无效回复数=各单元各自无效回复数之和\n\n\- 整体有效回复率=总有效回复数÷总需回复弹幕数×100%，保留1位小数\n\n\n\n3. **无效回复汇总**\n\n\- 完整复制每个单元中所有无效回复的具体情况（原单元总结中描述的无效回复原因）\n\n\- 按弹幕发送时间顺序排列所有无效回复\n\n\n\n\## 输出格式要求\n\n严格按照以下 **Markdown** 结构输出（与话术质检统一范式），不得增减任何区段，不得在指定区段外添加任何文字、代码块标记、注释或前后缀说明。\n\n\### 区段 1：弹幕明细表格\n\n按弹幕时间升序排列，输出所有需回复弹幕（不得遗漏），列固定 8 列：\n\n| 弹幕时间 (XX:XX:XX) | 用户昵称 | 弹幕内容 (疑问/求助) | 主播回复话术 | 回复时间 | 是否1分钟内回复 | 针对性回复判断依据 | 是否属于有效回复 |\n| --- | --- | --- | --- | --- | --- | --- | --- |\n| ... | ... | ... | ... | ... | ... | ... | ... |\n\n属于有效回复的最后一列单元格必须保留原有的 `<font color="red">是</font>` 格式。\n\n\### 区段 2：摘要总结段（必须用 `<aifupan-data-block>` 标签包裹）\n\n`<aifupan-data-block>` 标签内**仅放概要总结段（3-5 行）**，不包弹幕明细表格。格式：\n\n```\n<aifupan-data-block>\n本场直播整体互动有效回复率为 <X.X%，保留1位小数，含百分号>，总单元数 <N，整数>，需回复弹幕共 <X 条>，其中有效回复 <X 条>，无效回复 <X 条>。\n\n无效回复明细：\n1. <第 N 单元无效回复描述，一字不差复制原单元>\n2. <...>\n（若某单元无无效回复，标注"第 X 单元无无效回复"）\n</aifupan-data-block>\n```\n\n\## 严格约束\n\n1. **整个回复必须 Markdown 全文**，不得包 \```json\``` 代码块标记，不得在 Markdown 之外添加任何前后缀说明\n2. **`<aifupan-data-block>` 标签必须且仅出现一次**，包裹区段 2 摘要总结段；**不得在区段 1（弹幕表格）内出现该标签**\n3. 区段 2 的有效回复率必须保留 1 位小数（X.X% 含百分号字符串，如 `98.9%`）\n4. 区段 2 的无效回复明细必须**一字不差**地复制原单元分析中的表述，不得修改、简化或补充\n5. 若某单元无无效回复，标注 `第 X 单元无无效回复`\n\n\n\n\## 特殊要求\n\n\- 所有属于有效回复的单元格必须保留原有的`<font color="red">是</font>`格式\n\n\- 无效回复的描述必须**一字不差**地复制原单元分析中的表述，不得修改、简化或补充\n\n\- 若某单元无无效回复，标注"第X单元无无效回复"\n', 21, NOW(), NOW(), 0, 0
WHERE NOT EXISTS (SELECT 1 FROM tb_cue_words WHERE ask_type = 21 AND trade_id = 1 AND is_deleted = 0);
